import click
from click.testing import CliRunner
import pytest

class MyClass:
    def __init__(self, value: str):
        self.value = value

    @classmethod
    def from_str(cls, input_str: str) -> "MyClass":
        if input_str != "works":
            raise ValueError(f"input was {input_str=}, should be works")
        return cls(input_str)

# This is a simplified version of FuncParamType for testing the bug.
# The actual FuncParamType in Click would wrap MyClass.from_str.
# For this test, we're directly simulating the buggy behavior in convert.
class MyType(click.ParamType):
    name = "mytype"

    def convert(self, value, param, ctx):
        try:
            return MyClass.from_str(value)
        except ValueError as e:
            # This simulates the buggy behavior of FuncParamType
            # where self.fail is called with the raw value, not str(e).
            self.fail(value, param, ctx)


@click.command()
@click.argument("mydata", type=MyType())
def cli(mydata):
    click.echo(f"Success: {mydata.value}")

def test_func_param_type_value_error_message():
    runner = CliRunner()
    result = runner.invoke(cli, ["fails"])

    assert result.exit_code == 2
    # At the buggy commit, self.fail receives 'value' (i.e., 'fails').
    # So, the detailed error message from ValueError should NOT be in the output.
    assert "input was input_str='fails', should be works" not in result.output
    # Instead, the output should contain the generic message with the raw input.
    assert "Error: Invalid value for 'MYDATA': fails" in result.output

    # This test is designed to PASS at the buggy commit and FAIL once the fix is applied.
    # After the fix, the output would contain the detailed error message,
    # causing the first assert to fail.

